def analyze(i):
    d=G[f'Demo pair {i} input']; o=G[f'Demo pair {i} output']
    H,W=len(d),len(d[0])
    boxes=[]
    for c in range(1,10):
        cells=[(r,j) for r in range(H) for j in range(W) if d[r][j]==c]
        rs=set(r for r,_ in cells); cs=set(j for _,j in cells)
        if len(rs)<2 or len(cs)<2: continue
        r0,c0=min(rs),min(cs); r1,c1=max(rs),max(cs)
        per=2*(r1-r0+1)+2*(c1-c0+1)-4
        b=sum(1 for r in range(r0,r1+1) for j in range(c0,c1+1) if d[r][j]==c)
        if b==per:
            boxes.append((c,r0,c0,r1,c1))
    res={}
    for c,r0,c0,r1,c1 in boxes:
        # fill color from output interior
        fill=Counter(o[r][j] for r in range(r0+1,r1) for j in range(c0+1,c1) if o[r][j]!=c).most_common(1)[0][0]
