        def dist_to_box(p,box):
            r0,c0,r1,c1=box; dr=max(r0-p[0],p[0]-r1,0); dc=max(c0-p[1],p[1]-c1,0); return dr+dc
        info=[]
        for v in marks:
            pts=[(r,j) for r in range(H) for j in range(W) if d[r][j]==v]
            md=min(dist_to_box(p,(c,r0,c0,r1,c1)) for p in pts)
            info.append((v,md,len(pts)))
